    char("hello", min_chars = 3, shorten = "abbreviate"),
    char("ab", shorten = "back"),
    char(c("ab", "cd"), min_chars = 2, shorten = "front")
  )
  lapply(items, function(x) {
    list(data = x, type = format(attr(x, "pillar", exact = TRUE)))
  })
}

value <- one()
elapsed <- numeric(20)
